pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Inputs are assumed non-empty per problem statement.

    let mut xx: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut yy: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for i in 0..rows {
        // X: each row is the x vector
        xx.push(x.clone());

        // Y: each row is filled with y[i]
        yy.push(vec![y[i]; cols]);
    }

    (xx, yy)
}